(function(){"use strict";function init(){if(document.getElementById("baliMobileHamburger"))return;var body=document.body,rail=document.getElementById("baliUnifiedRail");if(!rail)return;var button=document.createElement("button");button.type="button";button.id="baliMobileHamburger";button.setAttribute("aria-label","Zobrazit ovládací tlačítka");button.setAttribute("aria-expanded","false");button.setAttribute("aria-controls","baliUnifiedRail");button.innerHTML='<span class="bali-hamburger-mark" aria-hidden="true">☰</span>';document.body.appendChild(button);function setExpanded(value){body.classList.toggle("bali-mobile-rail-open",!!value);button.setAttribute("aria-expanded",String(!!value));button.setAttribute("aria-label",value?"Skrýt ovládací tlačítka":"Zobrazit ovládací tlačítka");button.querySelector("span").textContent=value?"×":"☰"}button.addEventListener("click",function(event){event.preventDefault();event.stopPropagation();setExpanded(!body.classList.contains("bali-mobile-rail-open"))});button.addEventListener("pointerdown",function(event){event.stopPropagation()});rail.addEventListener("click",function(){});document.addEventListener("pointerdown",function(event){if(!body.classList.contains("bali-mobile-rail-open"))return;if(event.target.closest("#baliMobileHamburger,#baliUnifiedRail"))return;setExpanded(false)});document.addEventListener("keydown",function(event){if(event.key==="Escape")setExpanded(false)});window.addEventListener("resize",function(){if(window.innerWidth>700)setExpanded(false)},{passive:true})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();